<script setup lang="ts">
import {computed,ref} from 'vue'; import {useRoute} from 'vue-router'; import {Heart,Minus,Plus,ShoppingBag,Truck,ShieldCheck,Clock} from 'lucide-vue-next'; import {products,money} from '../data'; import {useShopStore} from '../stores/shop'; import ProductCard from '../components/ProductCard.vue';
const route=useRoute(),store=useShopStore(),qty=ref(1),selectedVariant=ref(''),selectedAddons=ref<string[]>([]),cakeText=ref(''); const p=computed(()=>products.find(x=>x.id===route.params.id)); const variant=computed(()=>p.value?.variants?.find(v=>v.id===selectedVariant.value)||p.value?.variants?.[0]); const unitPrice=computed(()=> (p.value?.price||0)+(variant.value?.price||0)+(p.value?.addons?.filter(a=>selectedAddons.value.includes(a.id)).reduce((n,a)=>n+a.price,0)||0)+(cakeText.value?p.value?.cakeText?.price||0:0)); const related=computed(()=>products.filter(x=>x.category===p.value?.category&&x.id!==p.value?.id).slice(0,4)); function add(){if(p.value)store.add(p.value,qty.value)}
</script>
<template><section v-if="p" class="section"><div class="container product-detail"><div class="detail-image"><img :src="p.image" :alt="p.name"><span class="tag">{{p.tags[0]}}</span></div><div class="detail-copy"><h1>{{p.name}}</h1><p class="arabic large">{{p.nameAr}}</p><strong class="detail-price">From {{money(p.price)}}</strong><p class="description">{{p.description}}</p><div class="info-pills"><span v-if="p.servings">Serves: {{p.servings}}</span><span>Made to order</span></div><div v-if="p.allergens" class="allergens"><b>Contains:</b> {{p.allergens.join(', ')}}</div><div v-if="p.variants" class="config"><b>Choose a size</b><div class="choice-grid"><button v-for="v in p.variants" :class="{selected:(selectedVariant||p.variants[0].id)===v.id}" @click="selectedVariant=v.id">{{v.name}} <small v-if="v.price">+ {{money(v.price)}}</small></button></div></div><div v-if="p.addons?.length" class="config"><b>Packaging</b><label v-for="a in p.addons" class="option-check"><input v-model="selectedAddons" type="checkbox" :value="a.id"> {{a.name}} <small>+ {{money(a.price)}}</small></label></div><label v-if="p.cakeText" class="cake-text"><b>Short cake text (optional)</b><small>+ {{money(p.cakeText.price)}} · up to {{p.cakeText.maxLength}} characters</small><input v-model="cakeText" :maxlength="p.cakeText.maxLength" placeholder="e.g. Happy Birthday Noor"></label><div class="purchase"><div class="qty"><button @click="qty=Math.max(1,qty-1)"><Minus :size="17"/></button><b>{{qty}}</b><button @click="qty++"><Plus :size="17"/></button></div><button class="btn primary grow" @click="add"><ShoppingBag :size="18"/> Add to Cart · {{money(unitPrice*qty)}}</button><button class="icon-btn" :class="{active:store.wishlist.includes(p.id)}" @click="store.toggleWish(p.id)"><Heart :fill="store.wishlist.includes(p.id)?'currentColor':'none'"/></button></div><div class="detail-trust"><span><Truck/> Delivery fee and earliest window are calculated after area selection</span><span><Clock/> Availability is confirmed by the bakery after ordering</span><span><ShieldCheck/> Cash on delivery only</span></div></div></div></section><section v-if="related.length" class="section alt"><div class="container"><div class="section-head"><div><span class="eyebrow">You May Also Like</span><h2>More to Love</h2></div></div><div class="product-grid"><ProductCard v-for="x in related" :key="x.id" :product="x"/></div></div></section></template>
